/* Global theme variables (light/dark + high contrast) */
:root[data-theme="light"] {
    --bg-primary: #ffffff;
    --bg-secondary: #f8f9fa;
    --text-primary: #1a1a1a;
    --text-secondary: #666666;
    --accent-color: #228B22;
    --accent-color-light: #228B22;
    --border-color: #dee2e6;
    --hover-bg: rgba(0, 0, 0, 0.05);
    --shadow-color: rgba(0, 0, 0, 0.1);
}
:root[data-theme="dark"] {
    --bg-primary: #1a1a1a;
    --bg-secondary: #2d2d2d;
    --text-primary: #ffffff;
    --text-secondary: #b3b3b3;
    --accent-color: #228B22;
    --accent-color-light: #228B22;
    --border-color: #404040;
    --hover-bg: rgba(255, 255, 255, 0.05);
    --shadow-color: rgba(0, 0, 0, 0.3);
}
/* Shared brand accents (available in both themes) */
:root {
    --ref-green: #00bfa6;
    --ref-green-600: #009e8a;
    --ref-green-50: #e6fcf7;
    --ref-amber: #ffd166;
    --surface-soft: #f6faf9;
    --shadow-soft: 0 8px 24px rgba(15,23,42,.06);
    --radius-lg: 16px;
    --radius-md: 12px;
    --anim-soft: 220ms cubic-bezier(.2,.7,.2,1);
}
/* Keep theme changes smooth without animating the entire DOM */
html,
body,
.navbar,
.card,
.modal-content,
.offcanvas,
.dropdown-menu,
.list-group-item,
.accordion-button,
.form-control,
.form-select,
.btn,
.alert {
    transition:
        background-color 0.18s ease,
        color 0.18s ease,
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
/* High contrast overrides */
@media (prefers-contrast: high) {
    :root[data-theme="light"],
    :root[data-theme="dark"] {
        --text-primary: #000000;
        --text-secondary: #000000;
        --accent-color: #000000;
        --border-color: #000000;
    }
}
/* Premium global polish: 20px rounding, subtle hover, clean actions */
:root {
  --primary-color: #00c4b4;
  --primary-dark: #00897b;
  --primary-light: #b2dfdb;
  --white-color: #ffffff;
  --gray-dark: #2a2a2a;
  --gray-medium: #4a4a4a;
  --gray-light: #f5f5f5;
}
/* Utilities */
.rounded-20 { border-radius: 20px !important; }
.elevate-hover { transition: transform 200ms ease, box-shadow 200ms ease; }
.elevate-hover:hover { transform: translateY(-2px); box-shadow: 0 12px 26px rgba(0,0,0,0.12); }
.focus-ring:focus, .focus-ring:focus-visible { outline: 3px solid rgba(0,137,123,0.35); outline-offset: 2px; }
/* Buttons, Inputs, Cards */
.btn { border-radius: 20px; }
.form-control, .form-select { border-radius: 20px; }
.input-group-text { border-radius: 0 20px 20px 0; }
.card { border-radius: 20px; box-shadow: 0 6px 18px rgba(0,191,166,0.12); }
.card:hover { box-shadow: 0 12px 26px rgba(0,0,0,0.12); }
/* Action row/buttons */
.action-row { display:flex; gap:12px; align-items:center; flex-wrap:wrap; }
.action-btn {
  display:inline-flex; align-items:center; gap:10px;
  padding:10px 16px; border:1px solid rgba(0,137,123,0.25);
  background:#fff; color:#0d3b3a; border-radius:20px;
  box-shadow:0 4px 10px rgba(0,0,0,0.06);
  transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease, color 160ms ease;
  font-weight:600;
}
.action-btn i { color:#00897b; }
.action-btn:hover { transform: translateY(-1px); box-shadow:0 8px 18px rgba(0,0,0,0.12); background:#f7fcfb; }
.action-btn:active { transform: translateY(0); }
.action-btn:focus, .action-btn:focus-visible { outline:3px solid rgba(0,137,123,0.3); outline-offset:2px; }
/* Scroll arrow enhancement (if used globally) */
.scroll-arrow:hover { box-shadow: 0 6px 14px rgba(0,137,123,0.25); }
.scroll-arrow:focus, .scroll-arrow:focus-visible { outline:3px solid rgba(0,137,123,0.35); }
