  align-items: flex-start;
  justify-content: space-between;
  gap: 0.9rem;
  border-radius: 14px;
  padding: 0.85rem 0.95rem;
  border: 1px solid rgba(255, 255, 255, 0.25);
  color: #fff;
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.25);
}

.premium-toast--success {
  background: #fff;
  color: #10363a;
  border-color: rgba(15, 110, 99, 0.24);
  box-shadow: 0 14px 30px rgba(10, 77, 70, 0.18);
}

.premium-toast--error {
  background: linear-gradient(135deg, #b42318, #7a1c16);
}

.premium-toast__copy {
  display: flex;
  flex-direction: column;
}

.premium-toast__title {
  font-weight: 700;
}

.premium-toast small {
  opacity: 0.9;
}

.premium-toast--success .btn-close {
  filter: none !important;
  opacity: 0.75;
}

.ic-footer {
  background: linear-gradient(140deg, #0b5e55, #073632);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  color: #fff;
}

.ic-footer__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding-top: 1rem;
  padding-bottom: calc(1rem + env(safe-area-inset-bottom));
}

.ic-footer__copy {
  font-weight: 600;
}

.ic-footer__brand {
  margin-left: 0.35rem;
  color: #fff;
  font-weight: 700;
  text-decoration: none;
}

.ic-footer__brand:hover {
  color: #fff;
  text-decoration: underline;
}

.ic-footer__social a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  margin-left: 0.4rem;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.45);
  color: #fff;
  transition: transform 0.2s ease, background-color 0.2s ease;
}

.ic-footer__social a:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  transform: translateY(-2px);
}

.premium-dialog-enter-active,
.premium-dialog-leave-active,
.premium-toast-enter-active,
.premium-toast-leave-active {
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.premium-dialog-enter-from,
.premium-dialog-leave-to,
.premium-toast-enter-from,
.premium-toast-leave-to {
  opacity: 0;
  transform: translateY(8px);
}

body.ic-dialog-open {
  overflow: hidden;
}

/* ─── Ayah of the Day ─── */

.ic-section--ayah {
  padding: clamp(2rem, 5vw, 3.5rem) 0;
  background: linear-gradient(180deg, #f5fbf8 0%, #edf7f3 100%);
  border-top: 1px solid rgba(15, 110, 99, 0.1);
  border-bottom: 1px solid rgba(15, 110, 99, 0.1);
}

.ic-ayah-section__intro {
  margin-bottom: 1.5rem;
}

.ic-ayah-card {
  padding: clamp(1.75rem, 4vw, 3rem);
  border-radius: 24px;
  background: linear-gradient(155deg, #ffffff 0%, #f8fdfb 100%);
  border: 1px solid rgba(15, 110, 99, 0.14);
  box-shadow: 0 18px 44px rgba(10, 48, 44, 0.09);
  position: relative;
  overflow: hidden;
}

.ic-ayah-card__ornament {
  position: absolute;
  top: -14px;
  right: 1.5rem;
  font-size: 3.5rem;
  line-height: 1;
  color: rgba(15, 110, 99, 0.08);
  pointer-events: none;
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
  font-family: "Amiri", serif;
}

.ic-ayah-card__arabic {
  font-family: "Amiri", "Scheherazade New", "Traditional Arabic", serif;
  font-size: clamp(1.15rem, 2vw, 1.55rem);
  line-height: 1.75;
  color: #0f3a3f;
  text-align: right;
}

.ic-ayah-card__arabic p {
  margin: 0;
}

.ic-ayah-card__content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  height: 100%;
  border-left: 3px solid rgba(15, 110, 99, 0.2);
  padding-left: 1.25rem;
}

.ic-ayah-card__translation {
  font-size: clamp(1rem, 1.5vw, 1.18rem);
  line-height: 1.72;
  color: #2f5258;
  font-style: italic;
  margin-bottom: 1rem;
}

.ic-ayah-card__meta {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.3rem;
  font-size: 0.84rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ic-ink-soft);
  margin: 0;
}

.ic-ayah-card__meta i {
  color: var(--ic-teal);
  font-size: 0.82rem;
}

.ic-ayah-card__dot {
  opacity: 0.45;
  margin: 0 0.1rem;
}

/* Fade transition between ayahs */

.ic-ayah-fade-enter-active,
.ic-ayah-fade-leave-active {
  transition: opacity 0.55s ease, transform 0.55s ease;
}

.ic-ayah-fade-enter-from,
.ic-ayah-fade-leave-to {
  opacity: 0;
  transform: translateY(8px);
}

/* Skeleton loader */

.ic-ayah-card--skeleton {
  pointer-events: none;
}

@keyframes ic-shimmer {
  0%   { background-position: -400px 0; }
  100% { background-position: 400px 0; }
}

.ic-ayah-skeleton__line {
  height: 0.9rem;
  border-radius: 6px;
  background: linear-gradient(90deg, #e8f2ef 25%, #d3ebe4 50%, #e8f2ef 75%);
  background-size: 800px 100%;
  animation: ic-shimmer 1.5s infinite linear;
}

.ic-ayah-skeleton__line--md   { width: 90%; }

.ic-ayah-skeleton__line--sm   { width: 70%; }

.ic-ayah-skeleton__line--xs   { width: 45%; height: 0.72rem; }

.ic-ayah-skeleton__line--arabic { width: 80%; height: 1.4rem; border-radius: 8px; }

@media (max-width: 991.98px) {
  .ic-hero {
    padding-top: 3.4rem;
  }

  .ic-hero__panel {
    padding: 1.3rem;
  }

  .ic-hero__title,
  .ic-hero__lead {
    text-align: center;
    margin-left: auto;
    margin-right: auto;
  }

  .ic-hero__badge,
  .ic-hero__actions,
  .ic-hero__trust {
    justify-content: center;
  }

}

@media (max-width: 767.98px) {
  .ic-hero {
    padding-top: 2.8rem;
  }

  .ic-hero__panel {
    padding: 1.1rem;
    border-radius: 16px;
  }

  .ic-section {
    padding: 3rem 0;
  }

  .section-lead {
    font-size: 0.98rem;
  }

  .ic-hero__actions .ic-btn {
    width: 100%;
    justify-content: center;
    min-height: 44px;
  }

  .ic-hero__trust-item {
    width: 100%;
    justify-content: center;
  }

  .ic-community {
    padding: 1.25rem;
  }

  .ic-channel-card__header {
    align-items: flex-start;
  }

  .premium-toast {
    left: 1rem;
    right: 1rem;
    min-width: 0;
    width: auto;
  }

  .ic-channel-card__icon {
    width: 42px;
    height: 42px;
    font-size: 1.1rem;
  }

  .ic-footer__inner {
    flex-direction: column;
  }

  .ic-footer__social a {
    margin: 0.2rem;
  }

  .ic-ayah-card__content {
    border-left: none;
    border-top: 3px solid rgba(15, 110, 99, 0.2);
    padding-left: 0;
    padding-top: 1.25rem;
  }

  .ic-ayah-card__arabic {
    text-align: center;
  }

  .ic-ayah-card__meta {
    justify-content: center;
  }

  .premium-dialog-actions > * {
    flex: 1 1 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ic-btn,
  .ic-link-card,
  .ic-feature-card,
  .ic-objective-card,
  .ic-channel-card,
  .ic-footer__social a,
  .premium-dialog-enter-active,
  .premium-dialog-leave-active,
  .premium-toast-enter-active,
  .premium-toast-leave-active,
  .ic-ayah-fade-enter-active,
  .ic-ayah-fade-leave-active {
    transition: none !important;
  }

  .ic-hero__panel > * {
    opacity: 1;
    animation: none !important;
  }

  .ic-ayah-skeleton__line {
    animation: none !important;
  }
}

/* --- Partners Section --- */

.ic-section--partners {
  position: relative;
  background: linear-gradient(135deg, #ffffff 0%, #f4fcf9 50%, #effff6 100%);
  border-top: 1px solid rgba(15, 110, 99, 0.08);
  border-bottom: 1px solid rgba(15, 110, 99, 0.08);
  overflow: hidden;
  padding: clamp(4rem, 8vw, 6.5rem) 0;
}

.ic-section--partners::before {
  content: "";
  position: absolute;
  top: -20%;
  right: -10%;
  width: 60%;
  height: 140%;
  background: radial-gradient(circle, rgba(15, 110, 99, 0.06) 0%, transparent 70%);
  transform: rotate(-15deg);
  pointer-events: none;
}

.ic-section--partners::after {
  content: "";
  position: absolute;
  bottom: -30%;
  left: -15%;
  width: 70%;
  height: 150%;
  background: radial-gradient(circle, rgba(210, 162, 75, 0.04) 0%, transparent 70%);
  pointer-events: none;
  animation: glow-pulse 12s ease-in-out infinite alternate;
}

@keyframes glow-pulse {
  from { opacity: 0.4; transform: scale(1); }
  to { opacity: 0.8; transform: scale(1.1); }
}

.ic-partner-card {
  padding: clamp(1.75rem, 3vw, 2.5rem);
  background: rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.8);
  border-radius: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
  box-shadow: 
    0 4px 20px -5px rgba(10, 48, 44, 0.05),
    inset 0 0 40px rgba(255, 255, 255, 0.2);
}

.ic-partner-card:hover {
  transform: translateY(-10px) scale(1.02);
  background: rgba(255, 255, 255, 0.95);
  border-color: rgba(15, 110, 99, 0.15);
  box-shadow: 
    0 30px 60px -12px rgba(10, 48, 44, 0.12),
    0 18px 36px -18px rgba(10, 48, 44, 0.1);
}

.ic-partner-card__icon {
  width: 72px;
  height: 72px;
  margin-bottom: 1.5rem;
  background: linear-gradient(135deg, rgba(15, 110, 99, 0.08), rgba(15, 110, 99, 0.04));
  color: var(--ic-teal);
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  transition: all 0.4s ease;
  position: relative;
  overflow: hidden;
}

.ic-partner-card__icon::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(45deg, transparent, rgba(255, 255, 255, 0.6), transparent);
  transform: translateX(-100%);
  transition: transform 0.6s ease;
}

.ic-partner-card:hover .ic-partner-card__icon {
  background: var(--ic-teal);
  color: white;
  transform: rotate(10deg);
  box-shadow: 0 12px 24px rgba(15, 110, 99, 0.25);
}

.ic-partner-card:hover .ic-partner-card__icon::after {
  transform: translateX(100%);
}

.ic-partner-card__name {
  margin: 0;
  font-family: var(--ic-title-font);
  font-size: clamp(1.05rem, 1.25vw, 1.2rem);
  font-weight: 700;
  color: #0f3a3f;
  letter-spacing: -0.02em;
}

