.quiz-option--correct {
  background: linear-gradient(135deg, #10b981, #22c55e);
  border-color: rgba(16, 185, 129, 0.8);
  color: #fff;
  box-shadow: 0 20px 40px rgba(16, 185, 129, 0.35);
  animation: quizOptionPop 0.3s ease-out;
}

.quiz-option--incorrect {
  background: linear-gradient(135deg, #ef4444, #f97316);
  border-color: rgba(239, 68, 68, 0.8);
  color: #fff;
  box-shadow: 0 20px 40px rgba(239, 68, 68, 0.28);
  animation: quizOptionShake 0.3s ease-in-out;
}

.quiz-option--neutral {
  background: #fff;
}

.quiz-option--selected {
  border-color: rgba(14, 165, 233, 0.8);
  box-shadow: 0 20px 40px rgba(14, 165, 233, 0.22);
  background: linear-gradient(135deg, rgba(14, 165, 233, 0.16), rgba(16, 185, 129, 0.08));
}

.quiz-feedback-panel {
  position: relative;
  overflow: hidden;
  border-radius: 18px;
  padding: 0.85rem 1rem;
  border: 1px solid rgba(15, 23, 42, 0.12);
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.08);
  animation: quizFeedbackPulse 0.35s ease-out;
}

.quiz-feedback-panel--correct {
  border-color: rgba(16, 185, 129, 0.55);
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.2), rgba(255, 255, 255, 0.95));
}

.quiz-feedback-panel--incorrect {
  border-color: rgba(239, 68, 68, 0.6);
  background: linear-gradient(135deg, rgba(239, 68, 68, 0.2), rgba(255, 255, 255, 0.95));
}

.quiz-feedback-panel--correct::before,
.quiz-feedback-panel--incorrect::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 6px;
  border-radius: 999px;
}

.quiz-feedback-panel--correct::before {
  background: linear-gradient(180deg, #10b981, #fbbf24);
}

.quiz-feedback-panel--incorrect::before {
  background: linear-gradient(180deg, #ef4444, #f97316);
}

.quiz-feedback-panel--correct .quiz-feedback-icon {
  background: rgba(16, 185, 129, 0.18);
  color: #0f766e;
}

.quiz-feedback-panel--incorrect .quiz-feedback-icon {
  background: rgba(239, 68, 68, 0.18);
  color: #b91c1c;
}

@keyframes quizFeedbackPulse {
  from {
    opacity: 0.65;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.quiz-options-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(180px, 1fr));
  gap: 0.9rem;
}

@keyframes quizOptionPop {
  0% {
    transform: translateY(-2px) scale(0.98);
  }
  60% {
    transform: translateY(-4px) scale(1.05);
  }
  100% {
    transform: translateY(-2px) scale(1);
  }
}

@keyframes quizOptionShake {
  0%,
  100% {
    transform: translateY(-2px) translateX(0);
  }
  25% {
    transform: translateY(-2px) translateX(-4px);
  }
  50% {
    transform: translateY(-2px) translateX(4px);
  }
  75% {
    transform: translateY(-2px) translateX(-2px);
  }
}

