  right: calc(env(safe-area-inset-right, 0) + clamp(1.5rem, 3.5vw, 2.5rem));
  width: clamp(44px, 3vw, 56px);
  height: clamp(44px, 3vw, 56px);
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.75);
  background: linear-gradient(135deg, #0f766e, #28d3b7);
  color: #fff;
